	@ParameterizedTest(name = "cancel instead of close={0}")
	@ValueSource(booleans = { false, true })
	void independentReaderAdmissionRechecksTheOwnerAfterItsActualReclaimer(boolean cancel) {
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(65536L, 65536L);
		NativeCancellationToken token = new NativeCancellationToken();
		AtomicInteger callbacks = new AtomicInteger();
		Throwable denied = null;
		NativeResultCursor unexpected = null;
		try (var ledger = memory.openQuery();
				var replay = new NativeResultReplay(new NativeResultRow.Schema("count"), null, token, ledger, 1048576L)) {
			replay.append(NativeResultRow.fromBindingSet(binding(PAYLOAD)));
			replay.finish();
			assertFalse(replay.spilled(), "the real large payload remains resident before reader pressure");
			try (NativeResultCursor first = replay.cursor();
					var pressure = ledger.reserve(ledger.maxBytes() - ledger.usedBytes() - 128L,
							new LmdbQueryMemoryManager.Reclaimable() {
								@Override public boolean shed() {
									callbacks.incrementAndGet();
									if (cancel) { token.requestCancellation(); }
									else { replay.close(); }
									return true;
								}
							})) {
				assertNotNull(pressure);
				try { unexpected = replay.cursor(); }
				catch (Throwable failure) { denied = failure; }
				if (unexpected != null) { unexpected.close(); }
				assertEquals(1, callbacks.get(), "actual independent-reader accounting invoked the real reclaimer");
				assertEquals(0L, pressure.bytes());
				if (cancel) {
					assertThrows(KernelQueryCancelledException.class, first::next);
				} else {
					assertEquals(binding(PAYLOAD), first.next().toBindingSet(),
							"an already accepted reader remains valid until its own close after producer retirement");
					assertTrue(first.next() == null);
				}
			}
			replay.close();
			assertEquals(0L, ledger.usedBytes(), "refused reader, existing reader and replay settle their claims");
		}
		assertEquals(0L, memory.usedBytes());
		if (cancel) {
			assertTrue(denied instanceof KernelQueryCancelledException,
					"cancellation inside admission refuses the new reader before it is published");
		} else {
			assertTrue(denied instanceof IllegalStateException,
					"a replay retired by reclamation cannot publish a newly admitted reader");
		}
		assertTrue(unexpected == null);
	}

	private static void assertSecondProducerAdmission(boolean spillFits) {
		String previous = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "1048576");
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(65536L, 65536L);
		var subject = VF.createIRI("urn:producer-ledger:s");
		var predicate = VF.createIRI("urn:producer-ledger:p");
		var source = SyntheticValueSource.forEvaluation(new LmdbNativeRepeatedStatementTermRoleTest.MemorySource(
				List.of(VF.createStatement(subject, predicate, subject)), subject));
		NativeExecutionContext enclosing = source.executionContext();
		ArrayList<NativeExecutionContext> owners = new ArrayList<>();
		NativeExecutionContext first = new NativeExecutionContext(); owners.add(first);
		NativeExecutionContext second = new NativeExecutionContext(); owners.add(second);
		// Worker facades retain their frame owner; a new lexical frame may in turn retain that worker's term
		// owner. Alternating the actual constructors gives a real, linear ownership closure without fake gates.
		for (int i = 0; i < 320; i++) {
			second = new NativeExecutionContext(second); owners.add(second);
			second = new NativeExecutionContext(second, EmptyBindingSet.getInstance()); owners.add(second);
		}
		Counter firstResource = new Counter(), secondResource = new Counter();
		first.nativeState(new Object(), () -> firstResource);
		second.nativeState(new Object(), () -> secondResource);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("count", 0), null); layout.freeze(List.of("count"));
		NativeGroupIteration group = new NativeGroupIteration(source, SlotPlan.empty(), layout, new int[0],
				new AggregateSpec[] {AggregateSpec.star("count")}, false, EmptyBindingSet.getInstance(), null, null, false, null);
		RuntimeException cleanup = spillFits ? null : new RuntimeException("second producer close");
		Producer firstRows = new Producer(first, PAYLOAD, null), secondRows = new Producer(second, "tail", cleanup);
		try (var ledger = memory.openQuery(); NativeReplayBindingList.Builder builder = new NativeReplayBindingList.Builder(group, ledger)) {
			builder.drain(firstRows);
			assertFalse(first.isClosed(), "the first distinct producer remains owned by the builder after EOF");
			assertEquals(1, firstRows.closes); assertEquals(0, firstResource.closes);
			assertTrue(ledger.usedBytes() > PAYLOAD.length(), "the large first payload is resident before pressure");
			// 4608 bytes admits the actual 4096-byte writer plus the tiny second row, but cannot admit the
			// second producer's >5KiB real owner array/table. The local replay cap still has ample space.
			long freeBytes = spillFits ? 4608L : 1024L;
			try (var pressure = ledger.reserve(ledger.maxBytes() - ledger.usedBytes() - freeBytes, null)) {
				assertNotNull(pressure, "ordinary independent query state creates the shared-ledger pressure");
				long beforeSecond = ledger.usedBytes();
				if (spillFits) {
					builder.drain(secondRows);
					assertTrue(ledger.usedBytes() < beforeSecond,
							"with no other reclaimer registered, releasing resident replay payload funds authority admission");
					assertFalse(second.isClosed()); assertEquals(0, secondResource.closes);
					List<BindingSet> result = builder.finish();
					assertEquals(List.of(binding(PAYLOAD), binding("tail")), result);
					assertTrue(result instanceof NativeReplayBindingList);
					group.close();
					assertEquals(pressure.bytes(), ledger.usedBytes(), "all replay rows/readers/source handles retire");
				} else {
					QueryEvaluationException failure = assertThrows(QueryEvaluationException.class, () -> builder.drain(secondRows));
					assertTrue(failure.getMessage().contains("memory"), "the exact ledger admission is the initiating failure");
					assertEquals(1, failure.getSuppressed().length); assertSame(cleanup, failure.getSuppressed()[0]);
					assertEquals(1, secondRows.position, "consumed input is never retried");
					assertThrows(IllegalStateException.class, builder::finish, "the refused replay cannot be published");
					assertEquals(pressure.bytes(), ledger.usedBytes(), "terminal admission failure settles the replay immediately");
				}
				assertTrue(first.isClosed()); assertTrue(second.isClosed());
				assertEquals(1, firstResource.closes); assertEquals(1, secondResource.closes);
				assertEquals(1, secondRows.closes);
			}
		} finally {
			group.close(); enclosing.close();
			for (int i = owners.size() - 1; i >= 0; i--) { owners.get(i).close(); }
			if (previous == null) { System.clearProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY); }
			else { System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previous); }
		}
		assertEquals(0L, memory.usedBytes());
	}

	private static BindingSet binding(String value) {
		MapBindingSet row = new MapBindingSet(); row.addBinding("count", VF.createLiteral(value)); return row;
	}

	private static final class Counter implements AutoCloseable {
		int closes;
		@Override public void close() { closes++; }
	}

	private static final class Producer implements NativeResultCursor {
		final NativeExecutionContext owner; final String value; final RuntimeException cleanup;
		int position, closes; boolean closed;
		Producer(NativeExecutionContext owner, String value, RuntimeException cleanup) { this.owner = owner; this.value = value; this.cleanup = cleanup; }
		@Override public NativeExecutionContext executionContext() { return owner; }
		@Override public NativeCancellationToken cancellation() { return owner.cancellation(); }
		@Override public NativeResultRow next() { return position++ == 0 ? NativeResultRow.fromBindingSet(binding(value)) : null; }
		@Override public void close() {
			if (closed) { return; } closed = true; closes++; owner.close(); if (cleanup != null) { throw cleanup; }
		}
	}
